/****
 * Component Page Handling (TSX/JSX files)
 */
import { computeHash, rendererLogger as logger } from "../utils/index.js";
import { createError, getErrorMessage, RENDER_ERROR, toError } from "../errors/index.js";
import { getProjectReact } from "../react/index.js";
import { buildComponentCacheKey } from "../cache/keys.js";
import { LRUCache } from "../utils/lru-wrapper.js";
import { registerLRUCache } from "../cache/index.js";
import { getDependencyPinningCacheKey } from "../transforms/esm/package-registry.js";
import { Singleflight } from "../utils/singleflight.js";
import { DEFAULT_REACT_VERSION } from "../transforms/import-rewriter/url-builder.js";
import { buildServerExternalPackagesIdentity } from "../config/server-external-packages.js";
/**
 * Cache for transformed component hydration bundles.
 * Keys are content-addressed and scoped to transform-affecting inputs.
 * Safe for multi-tenant use (project-scoped + content/transform-hashed).
 * Evicted when exceeding MAX_COMPONENT_CACHE_SIZE to prevent unbounded memory growth.
 */
const MAX_COMPONENT_CACHE_SIZE = 5_000;
const componentHydrationCache = new LRUCache({
    maxEntries: MAX_COMPONENT_CACHE_SIZE,
});
const componentHydrationFlights = new Singleflight();
const COMPONENT_HYDRATION_FLIGHT_STALE_EVICTION_MS = 5 * 60_000;
async function getBundleComponentForClientDeps() {
    const { transformToESM } = await import("../transforms/esm-transform.js");
    return { transformToESM };
}
// Register cache for monitoring
registerLRUCache("component-hydration-cache", componentHydrationCache);
async function buildComponentHydrationCacheHash(source, dev, moduleServerUrl, reactVersion, serverExternalPackages) {
    const sourceHash = await computeHash(source);
    const effectiveReactVersion = reactVersion ?? DEFAULT_REACT_VERSION;
    const legacyCacheIdentity = [
        sourceHash,
        moduleServerUrl ?? null,
        effectiveReactVersion,
    ];
    const serverExternalPackagesIdentity = buildServerExternalPackagesIdentity(serverExternalPackages);
    const packageScopedIdentity = serverExternalPackagesIdentity
        ? [...legacyCacheIdentity, serverExternalPackagesIdentity]
        : legacyCacheIdentity;
    // The compile mode decides minification, tree shaking and whether an inline
    // sourcemap is emitted, so two modes must never share one hydration entry.
    const cacheIdentity = JSON.stringify([
        ...packageScopedIdentity,
        dev ? "compile-dev" : "compile-production",
    ]);
    return (await computeHash(cacheIdentity)).slice(0, 16);
}
/**
 * Load and render a TSX/JSX component page
 */
export async function handleComponentPage(pageInfo, slug, projectDir, _componentRegistry, adapter, options) {
    try {
        logger.debug(`Loading TSX/JSX file: ${pageInfo.entity.path}`);
        // Node positions are injected by the SSR module loader (for all files
        // including this entry point) when dev || environment === "preview", so
        // injecting here too would double-inject and shift positions.
        const fileContent = await adapter.fs.readFile(pageInfo.entity.path);
        const dependencyPinningCacheKey = options?.dependencyPinningCacheKey ??
            await getDependencyPinningCacheKey(projectDir);
        const dev = options?.mode === "development";
        const clientModuleCode = options?.cachedClientModule ??
            (await bundleComponentForClient(fileContent, pageInfo.entity.path, projectDir, adapter, options?.moduleServerUrl, options?.projectId, options?.reactVersion, undefined, options?.moduleServerOrigin, dependencyPinningCacheKey, options?.dependencyPinningDependencies, options?.dependencyPinningSource, options?.serverExternalPackages, dev, options?.dependencyPinningConfiguredVersions));
        const { loadComponentFromSource } = await import("../modules/react-loader/index.js");
        const PageComponent = await loadComponentFromSource(fileContent, pageInfo.entity.path, projectDir, adapter, {
            projectId: options?.projectId ?? projectDir,
            dev,
            moduleServerUrl: options?.moduleServerUrl,
            moduleServerOrigin: options?.moduleServerOrigin,
            ssr: true,
            contentSourceId: options?.contentSourceId,
            reactVersion: options?.reactVersion,
            reactPeers: options?.reactPeers,
            serverExternalPackages: options?.serverExternalPackages,
            dependencyPinningCacheKey,
            dependencyPinningDependencies: options?.dependencyPinningDependencies,
            dependencyPinningConfiguredVersions: options?.dependencyPinningConfiguredVersions,
            dependencyPinningSource: options?.dependencyPinningSource,
            mode: options?.environment,
            signal: options?.signal,
        });
        if (!PageComponent) {
            throw toError(createError({
                type: "render",
                message: `Component does not export a default: ${pageInfo.entity.path}`,
            }));
        }
        const React = await getProjectReact(options?.reactVersion, adapter, options?.reactPeers);
        const pageElement = React.createElement(PageComponent, options?.props ?? {});
        const pageBundle = {
            compiledCode: "",
            frontmatter: pageInfo.entity.frontmatter ?? {},
            globals: {},
            headings: [],
            nodeMap: new Map(),
        };
        if (clientModuleCode)
            pageBundle.clientModuleCode = clientModuleCode;
        logger.debug(`Successfully loaded TSX/JSX component for ${slug}`);
        return { pageElement, pageBundle };
    }
    catch (error) {
        logger.error(`Failed to import TSX/JSX file: ${pageInfo.entity.path}`, error);
        throw RENDER_ERROR.create({
            detail: `Failed to load TSX/JSX component: ${error.message}`,
            context: { slug, error },
        });
    }
}
export async function bundleComponentForClient(source, filePath, projectDir, adapter, moduleServerUrl, projectId, reactVersion, injectedDeps, moduleServerOrigin, dependencyPinningCacheKey = "off", dependencyPinningDependencies, dependencyPinningSource, serverExternalPackages, 
/**
 * Compile the hydration bundle in development mode. Production renders must
 * leave this false: dev output is unminified, not tree-shaken and carries an
 * inline sourcemap that discloses the project source.
 */
dev = false, dependencyPinningConfiguredVersions) {
    try {
        const cacheHash = await buildComponentHydrationCacheHash(source, dev, moduleServerUrl, reactVersion, serverExternalPackages);
        const cacheKey = buildComponentCacheKey(projectId ?? projectDir, filePath, cacheHash, dependencyPinningCacheKey, moduleServerOrigin);
        const cached = componentHydrationCache.get(cacheKey);
        if (cached)
            return cached;
        const transformed = await componentHydrationFlights.do(cacheKey, async (control) => {
            const cachedDuringFlight = componentHydrationCache.get(cacheKey);
            if (cachedDuringFlight)
                return cachedDuringFlight;
            const { transformToESM } = injectedDeps ?? await getBundleComponentForClientDeps();
            const transformed = await transformToESM(source, filePath, projectDir, adapter, {
                projectId: projectId ?? projectDir,
                dev,
                jsxImportSource: "react",
                moduleServerUrl,
                moduleServerOrigin,
                reactVersion,
                serverExternalPackages,
                dependencyPinningCacheKey,
                dependencyPinningDependencies,
                dependencyPinningConfiguredVersions,
                dependencyPinningSource,
            });
            if (control.isCurrent()) {
                componentHydrationCache.set(cacheKey, transformed);
            }
            return transformed;
        }, {
            staleAfterMs: COMPONENT_HYDRATION_FLIGHT_STALE_EVICTION_MS,
            onStaleEvicted: () => {
                logger.warn("Evicted stale component hydration transform flight", { filePath });
            },
        });
        return transformed;
    }
    catch (error) {
        const errorMessage = getErrorMessage(error);
        logger.error("Failed to transform component for client hydration", {
            filePath,
            error: errorMessage,
        });
        throw toError(createError({
            type: "render",
            message: `Component transformation failed for ${filePath}: ${errorMessage}`,
        }));
    }
}
